import{z as l,x as i,o as B,c as C,q as n,j as r,D as t,d as a,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"券源与借券运营","description":"","frontmatter":{"title":"券源与借券运营","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/qo-stockloan-ops.md","filePath":"quant/qo-stockloan-ops.md","lastUpdated":1791413859000}'),d={name:"quant/qo-stockloan-ops.md"};function p(c,E,F,u,D,m){const A=i("Mermaid");return B(),C("div",null,[E[2]||(E[2]=n('<h1 id="券源与借券运营" tabindex="-1">券源与借券运营 <a class="header-anchor" href="#券源与借券运营" aria-label="Permalink to &quot;券源与借券运营&quot;">​</a></h1><div class="epigraph"><p>空头腿不是仓位符号取负，而是一条有供给方、有价格、有断供风险的供应链；运营把它从回测里的一行成本，变成每天都要续上的合同。</p><footer>—— 据 Duffie, Gârleanu and Pedersen, *JFE*, 2002；D&#39;Avolio, *JFE*, 2002 整理</footer></div><p><a href="/quant/mac-backtest-map">上一课</a>把宏观策略的回测收成四件套口径：vintage 首发值、as-of 连接、滚动窗口、迟滞敏感性，独立样本按周期数计，叙事计入 \\(N\\)。回测把账算对；账算对之后，钱每天真正过日子的地方是运营。本课程第一课从最像供应链的一块讲起：券。每份空头都是借来的——<a href="/quant/securities-lending">证券借贷与做空成本</a>写过费率与召回怎么进定价，<a href="/quant/cn-margin-lending-structure">融券与转融通</a>写过 A 股的制度结构；本课写运营侧：怎么把券变成每天可盘点、可续借、有断供预案的供给线。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>策略层习惯把「可空」写成静态集合：信号日能定位，就一直当它能空。运营看到的是库存：出借人构成、每笔合约的费率与到期、抵押在谁手里、哪些券已被召回。缺口因此不是「找不找得到券」，而是三条会断的线同时在场：<strong>存量</strong>——在借合约的到期与展期；<strong>流量</strong>——新增券需求从哪个池子里来；<strong>断供</strong>——召回、名单调出、暂停出借把已有空头变成强制回补。信号日可借与持有期可借是两个事件；把前者当后者，回测里的空头腿在实盘第一个召回潮就现原形。</p><h3 id="券源台账是这条供应链的账本" tabindex="-1">券源台账是这条供应链的账本 <a class="header-anchor" href="#券源台账是这条供应链的账本" aria-label="Permalink to &quot;券源台账是这条供应链的账本&quot;">​</a></h3><p>台账按合约粒度记：券、出借方、借入日与到期、费率、抵押与折算率、召回条款，向上勾稽中介月结，向下喂给组合系统当「可空集合」的唯一事实来源。研究端读的可用券清单与运营端读的合约台账若不是同一份数据，容量估计与实际供给就会漂移——「单一事实来源」与<a href="/quant/sl-registry">策略台账体系</a>是同一条不变量，只是对象换成了券。</p><p><span class="marginnote">「召回」（recall）就是出借人把借出去的券要回去：可能是自己要交割、基金赎回，或券本身变抢手了。借券合约不像房贷有固定期限，出借人通常随时可召回——所以每笔空头都背着一条「地基随时可能被抽走」的暗线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把券当库存管理，四个动作固定成日常。<strong>盘点</strong>：每日开盘前核对可借、在借、已召回三态，与中介数据对平；差异当天查清。<strong>计价</strong>：空头腿的日持有成本写成 \\(c_t=b_t-\\rho_t+\\kappa\\,\\lambda_t\\)——借券费率 \\(b_t\\) 减抵押品再投资收益 \\(\\rho_t\\)，加召回强度 \\(\\lambda_t\\) 乘以回补冲击 \\(\\kappa\\) 的期望项；这笔钱按天进损益归因，不做一次性预扣。<strong>到期阶梯</strong>：新借合约的到期日刻意错开，避免同一日集中展期——展期日是费率重议日，集中等于交出议价权。<strong>断供预案</strong>：对敞口前几名的名字预写「若断供先减哪条腿」，与<a href="/quant/sl-exit-mechanism">退出机制</a>同一逻辑：临场再想，动作一定偏晚。</p>',10)),(B(),r(s,null,{default:t(()=>[o(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20POOL%5B%22%E5%87%BA%E5%80%9F%E4%BA%BA%E6%B1%A0%E4%B8%8E%E5%88%B8%E6%BA%90%E8%AF%A2%E4%BB%B7%22%5D%20--%3E%20LOC%5B%22%E5%AE%9A%E4%BD%8D%E4%B8%8E%E5%80%9F%E5%85%A5%22%5D%0A%20%20LOC%20--%3E%20OPEN%5B%22%E5%9C%A8%E5%80%9F%EF%BC%9A%E8%B4%B9%E7%8E%87%20%2F%20%E6%8A%B5%E6%8A%BC%20%2F%20%E5%88%B0%E6%9C%9F%E5%85%A5%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20OPEN%20--%3E%20ROLL%7B%22%E5%88%B0%E6%9C%9F%E6%88%96%E5%B1%95%E6%9C%9F%22%7D%0A%20%20ROLL%20--%3E%7C%22%E7%BB%AD%E5%80%9F%EF%BC%9A%E9%87%8D%E8%AE%AE%E8%B4%B9%E7%8E%87%22%7C%20OPEN%0A%20%20ROLL%20--%3E%7C%22%E5%BD%92%E8%BF%98%22%7C%20CLOSED%5B%22%E7%A9%BA%E5%A4%B4%E8%85%BF%E8%A7%A3%E9%99%A4%E6%88%96%E6%8D%A2%E5%88%B8%22%5D%0A%20%20OPEN%20--%3E%20RECALL%7B%22%E5%8F%AC%E5%9B%9E%E9%80%9A%E7%9F%A5%22%7D%0A%20%20RECALL%20--%3E%7C%22%E9%99%90%E6%9C%9F%E5%9B%9E%E8%A1%A5%22%7C%20COVER%5B%22%E6%8C%89%E9%A2%84%E6%A1%88%E5%87%8F%E4%BB%93%E6%88%96%E6%8D%A2%E6%A0%87%E7%9A%84%22%5D%0A%20%20RECALL%20--%3E%7C%22%E5%86%8D%E5%80%9F%E6%88%90%E5%8A%9F%22%7C%20OPEN%0A%20%20COVER%20--%3E%20LEDGER%5B%22%E5%8F%B0%E8%B4%A6%E4%B8%89%E6%80%81%E6%9B%B4%E6%96%B0%EF%BC%9A%E5%8F%AF%E5%80%9F%20%2F%20%E5%9C%A8%E5%80%9F%20%2F%20%E5%B7%B2%E5%8F%AC%E5%9B%9E%22%5D%0A%20%20CLOSED%20--%3E%20LEDGER%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("为什么按供应链管而不是按成本管：召回把空头持有期变成随机停时，供给紧张时费率、召回强度与失败交收三者同源上涨——不是三个独立风险，是同一份供给曲线的三个读数。运营的意义是把这三个读数变成"),e("strong",null,"每天可观测的状态量"),a("：费率看询价，召回看通知流，断供看覆盖率。覆盖率 \\(\\text{cover}_t=L_t/D_t\\) 是可借库存对在借需求的倍数，跌破阈值就该在价格还好的时候主动减，而不是等通知到了被动市价回补。不这么做会错在哪：把券当静态持有，召回潮到来时的回补冲击全由自己吃；美国 T+1 拿掉了召回与交收的缓冲夜（"),e("a",{href:"/quant/us-t1-settlement"},"美国 T+1 结算"),a("），同样的预案整体提前了一天。")],-1)),(B(),r(s,null,{default:t(()=>[o(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E5%8F%AF%E5%80%9F%E5%BA%93%E5%AD%98%20L%EF%BC%9A%E5%87%BA%E5%80%9F%E4%BA%BA%E6%B1%A0%E4%BE%9B%E7%BB%99%22%5D%20--%3E%20C%7B%22%E8%A6%86%E7%9B%96%E7%8E%87%20cover%20%3D%20L%20%2F%20D%22%7D%0A%20%20D%5B%22%E5%9C%A8%E5%80%9F%E9%9C%80%E6%B1%82%20D%EF%BC%9A%E7%A9%BA%E5%A4%B4%E8%85%BF%E5%90%88%E8%AE%A1%22%5D%20--%3E%20C%0A%20%20C%20--%3E%7C%22cover%20%E6%98%8E%E6%98%BE%E9%AB%98%E4%BA%8E%E9%98%88%E5%80%BC%22%7C%20SAFE%5B%22%E6%AD%A3%E5%B8%B8%E7%BB%AD%E5%80%9F%E4%B8%8E%E5%B1%95%E6%9C%9F%22%5D%0A%20%20C%20--%3E%7C%22cover%20%E9%80%BC%E8%BF%91%E9%98%88%E5%80%BC%22%7C%20ACT%5B%22%E4%BB%B7%E6%A0%BC%E5%B0%9A%E5%8F%AF%E6%97%B6%E4%B8%BB%E5%8A%A8%E5%87%8F%E4%BB%93%E6%88%96%E6%8D%A2%E6%A0%87%E7%9A%84%22%5D%0A%20%20C%20--%3E%7C%22cover%20%E8%B7%8C%E7%A0%B4%E9%98%88%E5%80%BC%22%7C%20STRESS%5B%22%E5%8F%AC%E5%9B%9E%E6%BD%AE%E4%B8%8E%E8%B4%B9%E7%8E%87%E9%A3%99%E5%8D%87%E5%90%8C%E6%97%B6%E5%88%B0%E6%9D%A5%22%5D%0A%20%20STRESS%20--%3E%20PASS%5B%22%E8%A2%AB%E5%8A%A8%E5%B8%82%E4%BB%B7%E5%9B%9E%E8%A1%A5%EF%BC%9A%E5%86%B2%E5%87%BB%E5%85%A8%E7%94%B1%E8%87%AA%E5%B7%B1%E5%90%83%22%5D%0A%20%20ACT%20--%3E%20OK%5B%22%E5%86%B2%E5%87%BB%E6%88%90%E6%9C%AC%E5%8F%AF%E6%8E%A7%E5%9C%B0%E8%90%BD%E5%9C%B0%22%5D%0A%20%20PASS%20--%3E%20LOSS%5B%22%E5%9B%9E%E8%A1%A5%E5%86%B2%E5%87%BB%20%CE%BA%20%E6%94%BE%E5%A4%A7%E6%88%90%E5%AE%9E%E4%BA%8F%22%5D%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">覆盖率代入数字：某票可借库存 \\(L=500\\) 万股，全市场在借需求 \\(D=100\\) 万股，覆盖率 5 倍，供给宽松；若需求涨到 450 万股，覆盖率只剩约 1.1 倍——一次召回或一笔新增空头就能打穿。这时该在价格还好的时候主动减，而不是等通知。</span></p><p><span class="marginnote">特殊券费率是截面变量，年化可从贴近无风险利差涨到两位数甚至三位数百分比；按全样本均值预扣，恰好在供给最紧、召回概率最高的名字上系统性高估空头利润——那正是空头腿贡献 alpha 的地方。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写借券市场的定价机制与特殊性经济学，那是<a href="/quant/securities-lending">证券借贷与做空成本</a>的对象；转融通与两融的制度细节、前端检查规则见<a href="/quant/cn-margin-lending-structure">融券与转融通</a>与<a href="/quant/cn-compliance-map">合规红线与收束</a>，本课只管运营侧。抵押品再投资的信用风险、收入分成谈判、借贷协议法律文本不在本课展开，运营只需把条款字段记进台账并按字段执行。券源的报备与异常交易红线，留到合规单元。</p><p><span class="marginnote">常见误区：把空头成本当成回测里一个固定年化数字。实际费率是截面变量且随时跳变，同一天里冷门票可以是蓝筹的几十倍；按全样本均值预扣，等于在最容易断供的名字上系统性高估空头利润——而那正是 alpha 最集中的地方。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>券是一条供应链：存量（到期展期）、流量（新增需求）、断供（召回与调出），三线每天盘点。</li><li>台账按合约粒度记费率、抵押、到期与召回条款，是可空集合的单一事实来源。</li><li>空头腿成本按天计 \\(c_t=b_t-\\rho_t+\\kappa\\lambda_t\\)，进损益归因，不一次性预扣。</li><li>到期阶梯错开展期日；断供预案预写减仓次序，覆盖率 \\(\\text{cover}_t\\) 跌破阈值先动。</li><li>出处：Duffie, Gârleanu and Pedersen, <em>Securities Lending, Shorting, and Pricing</em>, <em>JFE</em>, 2002 与 D&#39;Avolio, <em>JFE</em>, 2002；中国制度口径见<a href="/quant/cn-margin-lending-structure">融券与转融通</a>。</li></ul>',7))])}const f=l(d,[["render",p]]);export{_ as __pageData,f as default};
